export function PromptHistory({
  latestPrompt = "{{latestPrompt}}",
  accent = "{{accent}}",
  showTimestamps = {{showTimestamps}},
  density = "{{density}}",
}) {
  const itemPad = density === "compact" ? "6px 10px" : "10px 12px";
  const older = [
    { text: "Draft a reply to the billing escalation", time: "14:02" },
    { text: "List open pull requests for this repo", time: "Yesterday" },
  ];
  return (
    <div style={{ maxWidth: 420, fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", background: "#FAF7F2" }}>
      <h3 style={{ margin: "0 0 10px", fontSize: 13, fontWeight: 600, textTransform: "uppercase", letterSpacing: ".04em", color: "#241430b3" }}>
        Previous prompts
      </h3>
      <ul style={{ listStyle: "none", margin: 0, padding: 0, display: "flex", flexDirection: "column", gap: 4 }}>
        <li style={{ display: "flex", alignItems: "baseline", gap: 10, padding: itemPad, borderRadius: 8, border: "1px solid", borderColor: accent, background: "#24143008" }}>
          <span aria-hidden="true" style={{ flex: "none", width: 6, height: 6, borderRadius: "50%", background: accent, alignSelf: "center" }} />
          <span style={{ flex: 1, minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{latestPrompt}</span>
          {showTimestamps && <span style={{ flex: "none", fontSize: 12, color: "#24143080" }}>just now</span>}
        </li>
        {older.map((item) => (
          <li key={item.text} style={{ display: "flex", alignItems: "baseline", gap: 10, padding: itemPad, borderRadius: 8, border: "1px solid transparent" }}>
            <span aria-hidden="true" style={{ flex: "none", width: 6, height: 6, borderRadius: "50%", background: "#24143033", alignSelf: "center" }} />
            <span style={{ flex: 1, minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{item.text}</span>
            {showTimestamps && <span style={{ flex: "none", fontSize: 12, color: "#24143080" }}>{item.time}</span>}
          </li>
        ))}
      </ul>
    </div>
  );
}
